import React, { useEffect, useRef, memo } from 'react';
import {
  View,
  Animated,
  StyleSheet,
  ViewStyle,
  LayoutAnimation,
  Platform,
  Dimensions,
} from 'react-native';
import Colors from '@/constants/colors';

const SCREEN_WIDTH = Dimensions.get('window').width;

/** Single shimmer bone — animated gradient sweep */
function ShimmerBone({
  width = '100%',
  height = 16,
  borderRadius = 8,
  style,
}: {
  width?: number | string;
  height?: number;
  borderRadius?: number;
  style?: ViewStyle;
}) {
  const translateX = useRef(new Animated.Value(-1)).current;

  useEffect(() => {
  const anim = Animated.loop(
    Animated.timing(translateX, {
      toValue: 1,
      duration: 1200,
      useNativeDriver: true,
    })
  );
  anim.start();
  return () => anim.stop();
  }, [translateX]);

  const boneWidth = typeof width === 'number' ? width : SCREEN_WIDTH;
  const shimmerWidth = boneWidth * 0.5;

  return (
  <View
    style={[
    {
      width: width as number,
      height,
      borderRadius,
      backgroundColor: Colors.surfaceLight,
      overflow: 'hidden',
    },
    style,
    ]}
  >
    <Animated.View
    style={[
      StyleSheet.absoluteFill,
      {
      transform: [
        {
        translateX: translateX.interpolate({
          inputRange: [-1, 1],
          outputRange: [-shimmerWidth, boneWidth + shimmerWidth],
        }),
        },
      ],
      },
    ]}
    >
    <View
      style={{
      width: shimmerWidth,
      height: '100%',
      backgroundColor: Platform.OS === 'web' ? 'rgba(255,255,255,0.06)' : 'rgba(255,255,255,0.08)',
