def fix_file(filepath):
    global files_fixed
    with open(filepath, 'r') as f:
        content = f.read()

    original = content

    # Pattern: a multi-line import block that has the ShimmerIndicator import line
    # injected in the middle of another import block.
    # Example:
    # import {
    # import { ShimmerIndicator } from '@/components/ShimmerIndicator';
    #   fetchRolesAndAssignments,
    #   ...
    # } from '@/lib/something';
    #
    # Fix: extract the ShimmerIndicator import, remove it from the middle,
    # and add it as a separate import line.

    # Find all occurrences of the injected import line within multi-line imports
    shimmer_import = "import { ShimmerIndicator } from '@/components/ShimmerIndicator';"
    shimmer_import_alt = "import { ShimmerIndicator } from \"@/components/ShimmerIndicator\";"

    if shimmer_import in content or shimmer_import_alt in content:
        # Check if the import is inside a multi-line import block (preceded by import { or , on previous line)
        lines = content.split('\n')
        new_lines = []
        has_shimmer_import = False

        for i, line in enumerate(lines):
            stripped = line.strip()

            # If this is a ShimmerIndicator import line
            if stripped == shimmer_import or stripped == shimmer_import_alt:
                # Check if previous line ends with { or , (meaning we're inside a multi-line import)
                if i > 0:
                    prev_stripped = new_lines[-1].strip() if new_lines else ''
                    if prev_stripped.endswith('{') or prev_stripped.endswith(',') or prev_stripped.endswith('('):
                        # This is injected in the middle - skip it here, we'll add it after the block
                        has_shimmer_import = True
                        continue
                # Otherwise keep it as a standalone import
                new_lines.append(line)
            else:
                new_lines.append(line)

        if has_shimmer_import:
            # Now add the ShimmerIndicator import after the last top-level import
            content = '\n'.join(new_lines)

            # Find the last import line that starts at column 0
            lines = content.split('\n')
            last_import_idx = -1
            for i, line in enumerate(lines):
                if line.startswith('import ') and '@/components/ShimmerIndicator' not in line:
                    last_import_idx = i

            if last_import_idx >= 0:
                lines.insert(last_import_idx + 1, "import { ShimmerIndicator } from '@/components/ShimmerIndicator';")
                content = '\n'.join(lines)

    if content != original:
        files_fixed += 1
        with open(filepath, 'w') as f:
            f.write(content)

for root_dir in ['app', 'components']:
    for root, dirs, files in os.walk(root_dir):
